 "content": "from collections import Counter


def transform(grid):
    """Reduce each 3x3 cell to its non-background marker, if present."""
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            markers = [grid[i][j] for i in range(r, min(r + 3, h))
                       for j in range(c, min(c + 3, w))
                       if grid[i][j] not in (0, 5)]
            row.append(Counter(markers).most_common(1)[0][0] if markers else 0)
        out.append(row)
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.loads(sys.stdin.read()))))
